create_tax_country_tax.code:
const countryTax = {
    country_code: 'NZ',
    name: 'New Zealand',
    tax_rate: 4.5,
    tax_method: 'FIXED_RATE',
    is_default: false,
};
const response = await client.taxCountryTaxes.createTaxCountryTax({country_tax: countryTax});
console.log(response.map.country_tax.id, response.map.country_tax.rate_display);

